CREATE TABLE orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,status ENUM('pending','paid','shipped','cancelled') NOT NULL DEFAULT 'pending',total_cents BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT now(),updated_at TIMESTAMP NOT NULL DEFAULT now(),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX orders_user_id(user_id),INDEX orders_status(status)) ENGINE=InnoDB
-- NEXT
CREATE TABLE order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,quantity INT NOT NULL CHECK(quantity>0),unit_price_cents BIGINT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id),INDEX order_items_order_id(order_id),INDEX order_items_product_id(product_id)) ENGINE=InnoDB
